    "0EA5E9","38BDF8","0EA5E9","7DD3FC","22D3EE",
    "10B981","34D399","F59E0B","FB923C","F97316","EF4444"
  ],
  speedBars: [
    "10B981","34D399","22D3EE","38BDF8","0EA5E9",
    "F59E0B","FB923C","F97316","EF4444","DC2626"
  ],
  priceBars: [
    "10B981","22D3EE","34D399","38BDF8",
    "0EA5E9","F59E0B","FB923C","F97316","EF4444","DC2626"
  ]
};

// ── Factory helpers ────────────────────────────────────
const mkShadow = () => ({
  type: "outer", blur: 8, offset: 2, angle: 135,
  color: "000000", opacity: 0.12
});

const mkCard = (slide, x, y, w, h, opts = {}) => {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w, h,
    fill: { color: C.white },
    shadow: mkShadow(),
    ...opts
  });
};

const addSlideNum = (slide, num) => {
  slide.addText(String(num), {
    x: 9.2, y: 5.15, w: 0.5, h: 0.3,
    fontSize: 9, color: C.textMuted, align: "right", margin: 0
  });
};

const addSource = (slide) => {
  slide.addText("Source: Artificial Analysis, April 2026", {
    x: 0.5, y: 5.15, w: 4, h: 0.3,
    fontSize: 8, color: C.textMuted, margin: 0
  });
};

// ── Data ───────────────────────────────────────────────
