const pptxgen = require("pptxgenjs");
const path = require("path");
const fs = require("fs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Artificial Analysis";
pres.title = "AI Model Landscape April 2026";

// ── Color Palette ──────────────────────────────────────
const C = {
  darkBg:    "0F172A",
  darkCard:  "1E293B",
  lightBg:   "F8FAFC",
  white:     "FFFFFF",
  accent:    "0EA5E9",
  accent2:   "10B981",
  accent3:   "F59E0B",
  accentRed: "EF4444",
  textLight: "F1F5F9",
  textDark:  "1E293B",
  textMuted: "64748B",
