  { model: "gpt-oss-120B (high)", provider: "OpenAI", score: 33 }
];

const speedData = [
  { model: "gpt-oss-120B (high)", speed: 218 },
  { model: "Grok 4.20 0309 v2", speed: 188 },
  { model: "NVIDIA Nemotron 3 Super", speed: 172 },
  { model: "Gemini 3 Flash", speed: 153 },
  { model: "Gemini 3.1 Pro Preview", speed: 118 },
  { model: "GPT-5.4 (xhigh)", speed: 83 },
  { model: "GLM-5.1", speed: 64 },
  { model: "Claude Sonnet 4.6 (max)", speed: 63 },
  { model: "Claude Opus 4.6 (max)", speed: 49 },
  { model: "DeepSeek V3.2", speed: 46 }
];

