  { model: "gpt-oss-120B (high)", price: 0.30 },
  { model: "DeepSeek V3.2", price: 0.30 },
  { model: "NVIDIA Nemotron 3 Super", price: 0.40 },
  { model: "Gemini 3 Flash", price: 1.10 },
  { model: "GLM-5.1", price: 2.10 },
  { model: "Grok 4.20 0309 v2", price: 3.00 },
  { model: "Gemini 3.1 Pro Preview", price: 4.50 },
  { model: "GPT-5.4 (xhigh)", price: 5.60 },
  { model: "Claude Sonnet 4.6 (max)", price: 6.00 },
  { model: "Claude Opus 4.6 (max)", price: 10.00 }
];

// ═══════════════════════════════════════════════════════
// SLIDE 1 — TITLE
// ═══════════════════════════════════════════════════════
{
  const s = pres.addSlide();
