    bold: true, margin: 0
  });
  s.addText("Benchmarking Intelligence, Speed, and Cost Across 11 Frontier Models", {
    x: 0.8, y: 3.3, w: 8.4, h: 0.6,
    fontSize: 16, fontFace: "Calibri", color: C.textMuted, margin: 0
  });

  // Bottom bar
