    x: 0, y: 5.1, w: 10, h: 0.525,
    fill: { color: C.darkCard }
  });
  s.addText("Data source: Artificial Analysis  |  Captured April 10, 2026  |  artificialanalysis.ai", {
    x: 0.8, y: 5.15, w: 8.4, h: 0.35,
    fontSize: 10, fontFace: "Calibri", color: C.textMuted, margin: 0
  });
