const pptxgen = require("pptxgenjs");
const path = require("path");
const fs = require("fs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Artificial Analysis";
pres.title = "AI Model Landscape April 2026";

// ── Color Palette ──────────────────────────────────────
const C = {
  darkBg:    "0F172A",
  darkCard:  "1E293B",
  lightBg:   "F8FAFC",
  white:     "FFFFFF",
  accent:    "0EA5E9",
  accent2:   "10B981",
  accent3:   "F59E0B",
  accentRed: "EF4444",
  textLight: "F1F5F9",
  textDark:  "1E293B",
  textMuted: "64748B",
  border:    "E2E8F0",
  chartBars: [
    "0EA5E9","38BDF8","0EA5E9","7DD3FC","22D3EE",
    "10B981","34D399","F59E0B","FB923C","F97316","EF4444"
  ],
  speedBars: [
    "10B981","34D399","22D3EE","38BDF8","0EA5E9",
    "F59E0B","FB923C","F97316","EF4444","DC2626"
  ],
  priceBars: [
    "10B981","22D3EE","34D399","38BDF8",
    "0EA5E9","F59E0B","FB923C","F97316","EF4444","DC2626"
  ]
};

// ── Factory helpers ────────────────────────────────────
const mkShadow = () => ({
  type: "outer", blur: 8, offset: 2, angle: 135,
  color: "000000", opacity: 0.12
});

const mkCard = (slide, x, y, w, h, opts = {}) => {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w, h,
    fill: { color: C.white },
    shadow: mkShadow(),
    ...opts
  });
};

const addSlideNum = (slide, num) => {
  slide.addText(String(num), {
    x: 9.2, y: 5.15, w: 0.5, h: 0.3,
    fontSize: 9, color: C.textMuted, align: "right", margin: 0
  });
};

const addSource = (slide) => {
  slide.addText("Source: Artificial Analysis, April 2026", {
    x: 0.5, y: 5.15, w: 4, h: 0.3,
    fontSize: 8, color: C.textMuted, margin: 0
  });
};

// ── Data ───────────────────────────────────────────────
const intelData = [
  { model: "Gemini 3.1 Pro Preview", provider: "Google", score: 57 },
  { model: "GPT-5.4 (xhigh)", provider: "OpenAI", score: 57 },
  { model: "Claude Opus 4.6 (max)", provider: "Anthropic", score: 53 },
  { model: "Muse Spark", provider: "Meta", score: 52 },
  { model: "Claude Sonnet 4.6 (max)", provider: "Anthropic", score: 52 },
  { model: "GLM-5.1", provider: "Z AI", score: 51 },
  { model: "Grok 4.20 0309 v2", provider: "xAI", score: 49 },
  { model: "Gemini 3 Flash", provider: "Google", score: 46 },
  { model: "DeepSeek V3.2", provider: "DeepSeek", score: 42 },
  { model: "NVIDIA Nemotron 3 Super", provider: "NVIDIA", score: 36 },
  { model: "gpt-oss-120B (high)", provider: "OpenAI", score: 33 }
];

const speedData = [
  { model: "gpt-oss-120B (high)", speed: 218 },
  { model: "Grok 4.20 0309 v2", speed: 188 },
  { model: "NVIDIA Nemotron 3 Super", speed: 172 },
  { model: "Gemini 3 Flash", speed: 153 },
  { model: "Gemini 3.1 Pro Preview", speed: 118 },
  { model: "GPT-5.4 (xhigh)", speed: 83 },
  { model: "GLM-5.1", speed: 64 },
  { model: "Claude Sonnet 4.6 (max)", speed: 63 },
  { model: "Claude Opus 4.6 (max)", speed: 49 },
  { model: "DeepSeek V3.2", speed: 46 }
];

const priceData = [
  { model: "gpt-oss-120B (high)", price: 0.30 },
  { model: "DeepSeek V3.2", price: 0.30 },
  { model: "NVIDIA Nemotron 3 Super", price: 0.40 },
  { model: "Gemini 3 Flash", price: 1.10 },
  { model: "GLM-5.1", price: 2.10 },
  { model: "Grok 4.20 0309 v2", price: 3.00 },
  { model: "Gemini 3.1 Pro Preview", price: 4.50 },
  { model: "GPT-5.4 (xhigh)", price: 5.60 },
  { model: "Claude Sonnet 4.6 (max)", price: 6.00 },
  { model: "Claude Opus 4.6 (max)", price: 10.00 }
];

// ═══════════════════════════════════════════════════════
// SLIDE 1 — TITLE
// ═══════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };

