bold: true, margin: 0\n  });\n\n  // Key takeaway card below table\n  mkCard(s, 5.7, 2.95, 4.0, 2.0);\n  s.addShape(pres.shapes.RECTANGLE, {\n    x: 5.7, y: 2.95, w: 0.06, h: 2.0,\n    fill: { color: C.accent3 }\n  });\n  s.addText([\n    { text: \"Every model requires trade-offs\", options: { bold: true, fontSize: 13, color: C.textDark, breakLine: true } },\n    { text: \"\", options: { breakLine: true, fontSize: 6 } },\n    { text: \"High intelligence → lower speed, higher cost\", options: { fontSize: 10, color: C.textMuted, breakLine: true } },\n    { text: \"High speed → lower intelligence scores\", options: { fontSize: 10, color: C.textMuted, breakLine: true } },\n    { text: \"Low cost → sacrifices on capability\", options: { fontSize: 10, color: C.textMuted, breakLine: true } },\n    { text: \"\", options: { breakLine: true, fontSize: 4 } },\n    { text: \"Selection must be use-case driven.\", options: { fontSize: 11, color: C.accent3, bold: true } }\n  ], { x: 5.95, y: 3.1, w: 3.55, h: 1.7, margin: 0, valign: \"top\" });\n\n  addSource(s);\n  addSlideNum(s, 5);\n}\n\n// ═══════════════════════════════════════════════════════\n// SLIDE 6 — TAKEAWAYS\n// ═══════════════════════════════════════════════════════\n{\n  const s = pres.addSlide();\n  s.background = { color: C.darkBg };\n\n  // Top accent bar\n  s.addShape(pres.shapes.RECTANGLE, {\n    x: 0, y: 0, w: 10, h: 0.06,\n    fill: { color: C.accent2 }\n  });\n\n  s.addText(\"Open Weights Close the Gap: GLM-5.1 Reaches 51 Intelligence at $2.10/M Tokens\", {\n    x: 0.6, y: 0.3, w: 8.8, h: 0.7,\n    fontSize: 22, fontFace: \"Georgia\", color: C.textLight,\n    bold: true, margin: 0\n  });\n\n  // Three finding cards\n  const findings = [\n    {\n      accent: C.accent,\n      title: \"Intelligence is contested\",\n      body: \"Gemini 3.1 Pro Preview and GPT-5.4 tie at 57. The 57-to-33 spread shows not all \\\"frontier\\\" models are equal — verify benchmarks for your domain.\"\n    },\n    {\n      accent: C.accent2,\n      title: \"Speed and intelligence are inversely correlated\",\n      body: \"The fastest model (218 tok/s) scores only 33 on intelligence. For latency-sensitive pipelines, Gemini 3 Flash balances 153 tok/s with Intelligence 46.\"\n    },\n    {\n      accent: C.accent3,\n      title: \"Open-weight models are closing the gap\",\n      body: \"GLM-5.1 (51 intelligence, $2.10/M tokens) is within 10% of proprietary leaders. gpt-oss-120B leads on speed (218 tok/s) and ties on price ($0.30/M tokens).\"\n    }\n  ];\n\n  findings.forEach((f, i) => {\n    const cy = 1.2 + i * 1.2;\n    mkCard(s, 0.6, cy, 8.8, 1.0, { fill: { color: C.darkCard } });\n    s.addShape(pres.shapes.RECTANGLE, {\n      x: 0.6, y: cy, w: 0.06, h: 1.0,\n      fill: { color: f.accent }\n    });\n    s.addText(f.title, {\n      x: 0.85, y: cy + 0.08, w: 8.3, h: 0.35,\n      fontSize: 14, fontFace: \"Georgia\", color: f.accent,\n      bold: true, margin: 0\n    });\n    s.addText(f.body, {\n      x: 0.85, y: cy + 0.42, w: 8.3, h: 0.5,\n      fontSize: 11, fontFace: \"Calibri\", color: C.textMuted, margin: 0\n    });\n  });\n\n  // Recommendation bar at bottom\n  s.addShape(pres.shapes.RECTANGLE, {\n    x: 0.6, y: 4.7, w: 8.8, h: 0.55,\n    fill: { color: C.accent }, transparency: 85\n  });\n  s.addShape(pres.shapes.RECTANGLE, {\n    x: 0.6, y: 4.7, w: 0.06, h: 0.55,\n    fill: { color: C.accent }\n  });\n  s.addText(\"Recommendation: Define your workload priorities first, then select models that optimize the axis that matters most — intelligence, speed, or cost.\", {\n    x: 0.85, y: 4.73, w: 8.3, h: 0.5,\n    fontSize: 11, fontFace: \"Calibri\", color: C.textLight,\n    bold: true, margin: 0, valign: \"middle\"\n  });\n\n  // Bottom bar\n  s.addShape(pres.shapes.RECTANGLE, {\n    x: 0, y: 5.35, w: 10, h: 0.275,\n    fill: { color: C.darkCard }\n  });\n  s.addText(\"Artificial Analysis  |  April 2026\", {\n    x: 0.6, y: 5.35, w: 8.8, h: 0.27,\n    fontSize: 8, fontFace: \"Calibri\", color: C.textMuted, margin: 0\n  });\n  addSlideNum(s, 6);\n}\n\n// ── Write file ─────────────────────────────────────────\nconst outPath = \"/app/output/final_deck.pptx\";\npres.writeFile({ fileName: outPath }).then(() => {\n  console.log(\"Done:\", outPath);\n}).catch(err => {\n  console.error(\"Error:\", err);\n  process.exit(1);\n});\n", "numLines": 564, "startLine": 1, "totalLines": 564}}

