const pptxgen = require("pptxgenjs");
const path = require("path");
const fs = require("fs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Artificial Analysis";
pres.title = "AI Model Landscape April 2026";

// ── Color Palette ──────────────────────────────────────
const C = {
  darkBg:    "0F172A",
  darkCard:  "1E293B",
  lightBg:   "F8FAFC",
  white:     "FFFFFF",
  accent:    "0EA5E9",
  accent2:   "10B981",
  accent3:   "F59E0B",
  accentRed: "EF4444",
  textLight: "F1F5F9",
  textDark:  "1E293B",
  textMuted: "64748B",
  border:    "E2E8F0",
  chartBars: [
    "0EA5E9","38BDF8","0EA5E9","7DD3FC","22D3EE",
    "10B981","34D399","F59E0B","FB923C","F97316","EF4444"
  ],
  speedBars: [
    "10B981","34D399","22D3EE","38BDF8","0EA5E9",
    "F59E0B","FB923C","F97316","EF4444","DC2626"
  ],
  priceBars: [
    "10B981","22D3EE","34D399","38BDF8",
    "0EA5E9","F59E0B","FB923C","F97316","EF4444","DC2626"
  ]
};

// ── Factory helpers ────────────────────────────────────
const mkShadow = () => ({
  type: "outer", blur: 8, offset: 2, angle: 135,
  color: "000000", opacity: 0.12
});

const mkCard = (slide, x, y, w, h, opts = {}) => {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w, h,
    fill: { color: C.white },
    shadow: mkShadow(),
    ...opts
  });
};

const addSlideNum = (slide, num) => {
  slide.addText(String(num), {
    x: 9.2, y: 5.15, w: 0.5, h: 0.3,
    fontSize: 9, color: C.textMuted, align: "right", margin: 0
  });
};

const addSource = (slide) => {
  slide.addText("Source: Artificial Analysis, April 2026", {
    x: 0.5, y: 5.15, w: 4, h: 0.3,
    fontSize: 8, color: C.textMuted, margin: 0
  });
};

// ── Data ───────────────────────────────────────────────
const intelData = [
  { model: "Gemini 3.1 Pro Preview", provider: "Google", score: 57 },
  { model: "GPT-5.4 (xhigh)", provider: "OpenAI", score: 57 },
  { model: "Claude Opus 4.6 (max)", provider: "Anthropic", score: 53 },
  { model: "Muse Spark", provider: "Meta", score: 52 },
  { model: "Claude Sonnet 4.6 (max)", provider: "Anthropic", score: 52 },
  { model: "GLM-5.1", provider: "Z AI", score: 51 },
  { model: "Grok 4.20 0309 v2", provider: "xAI", score: 49 },
  { model: "Gemini 3 Flash", provider: "Google", score: 46 },
  { model: "DeepSeek V3.2", provider: "DeepSeek", score: 42 },
  { model: "NVIDIA Nemotron 3 Super", provider: "NVIDIA", score: 36 },
  { model: "gpt-oss-120B (high)", provider: "OpenAI", score: 33 }
];

const speedData = [
  { model: "gpt-oss-120B (high)", speed: 218 },
  { model: "Grok 4.20 0309 v2", speed: 188 },
  { model: "NVIDIA Nemotron 3 Super", speed: 172 },
  { model: "Gemini 3 Flash", speed: 153 },
  { model: "Gemini 3.1 Pro Preview", speed: 118 },
  { model: "GPT-5.4 (xhigh)", speed: 83 },
  { model: "GLM-5.1", speed: 64 },
  { model: "Claude Sonnet 4.6 (max)", speed: 63 },
  { model: "Claude Opus 4.6 (max)", speed: 49 },
  { model: "DeepSeek V3.2", speed: 46 }
];

const priceData = [
  { model: "gpt-oss-120B (high)", price: 0.30 },
  { model: "DeepSeek V3.2", price: 0.30 },
  { model: "NVIDIA Nemotron 3 Super", price: 0.40 },
  { model: "Gemini 3 Flash", price: 1.10 },
  { model: "GLM-5.1", price: 2.10 },
  { model: "Grok 4.20 0309 v2", price: 3.00 },
  { model: "Gemini 3.1 Pro Preview", price: 4.50 },
  { model: "GPT-5.4 (xhigh)", price: 5.60 },
  { model: "Claude Sonnet 4.6 (max)", price: 6.00 },
  { model: "Claude Opus 4.6 (max)", price: 10.00 }
];

// ═══════════════════════════════════════════════════════
// SLIDE 1 — TITLE
// ═══════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };

  // Decorative accent bar at top
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: C.accent }
  });

  // Large stat callout
  s.addText("11", {
    x: 0.8, y: 0.7, w: 1.2, h: 1.0,
    fontSize: 64, fontFace: "Georgia", color: C.accent,
    bold: true, margin: 0
  });
  s.addText("frontier models benchmarked", {
    x: 0.8, y: 1.55, w: 3.5, h: 0.35,
    fontSize: 13, fontFace: "Calibri", color: C.textMuted, margin: 0
  });

  // Vertical divider
  s.addShape(pres.shapes.RECTANGLE, {
    x: 4.6, y: 0.7, w: 0.03, h: 1.2,
    fill: { color: C.darkCard }
  });

  // Key stats
  const statsData = [
    { val: "57", label: "Top Intelligence Index (tie)" },
    { val: "218", label: "Max Output Tokens/s" },
    { val: "33x", label: "Price Gap (cheapest vs priciest)" }
  ];
  statsData.forEach((st, i) => {
    const bx = 5.0 + i * 1.7;
    s.addText(st.val, {
      x: bx, y: 0.7, w: 1.5, h: 0.7,
      fontSize: 32, fontFace: "Georgia", color: C.accent2, bold: true, margin: 0
    });
    s.addText(st.label, {
      x: bx, y: 1.35, w: 1.5, h: 0.55,
      fontSize: 9, fontFace: "Calibri", color: C.textMuted, margin: 0
    });
  });

  // Title
  s.addText("AI Model Landscape April 2026", {
    x: 0.8, y: 2.4, w: 8.4, h: 0.9,
    fontSize: 36, fontFace: "Georgia", color: C.textLight,
    bold: true, margin: 0
  });
  s.addText("Benchmarking Intelligence, Speed, and Cost Across 11 Frontier Models", {
    x: 0.8, y: 3.3, w: 8.4, h: 0.6,
    fontSize: 16, fontFace: "Calibri", color: C.textMuted, margin: 0
  });

  // Bottom bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.1, w: 10, h: 0.525,
    fill: { color: C.darkCard }
  });
  s.addText("Data source: Artificial Analysis  |  Captured April 10, 2026  |  artificialanalysis.ai", {
    x: 0.8, y: 5.15, w: 8.4, h: 0.35,
    fontSize: 10, fontFace: "Calibri", color: C.textMuted, margin: 0
  });
}

// ═══════════════════════════════════════════════════════
// SLIDE 2 — INTELLIGENCE RANKING
// ═══════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };

  // Title
  s.addText("Gemini 3.1 Pro Preview and GPT-5.4 Co-Lead the Intelligence Index at 57", {
    x: 0.5, y: 0.25, w: 9, h: 0.75,
    fontSize: 20, fontFace: "Georgia", color: C.textDark,
    bold: true, margin: 0
  });

  // Bar chart
  s.addChart(pres.charts.BAR, [{
    name: "Intelligence Index",
    labels: intelData.map(d => d.model),
    values: intelData.map(d => d.score)
  }], {
    x: 0.3, y: 1.1, w: 6.5, h: 4.0,
    barDir: "bar",
    chartColors: C.chartBars,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.textDark,
    dataLabelFontSize: 10,
    catAxisLabelColor: C.textDark,
    catAxisLabelFontSize: 9,
    valAxisHidden: true,
    catGridLine: { style: "none" },
    valGridLine: { color: C.border, size: 0.5 },
    showLegend: false,
    chartArea: { fill: { color: C.white }, roundedCorners: true }
  });

  // Callout card on the right
  mkCard(s, 7.1, 1.1, 2.6, 2.2);
  s.addShape(pres.shapes.RECTANGLE, {
    x: 7.1, y: 1.1, w: 0.06, h: 2.2,
    fill: { color: C.accent }
  });
  s.addText([
    { text: "Key Insight", options: { bold: true, fontSize: 13, color: C.textDark, breakLine: true } },
    { text: "", options: { breakLine: true, fontSize: 6 } },
    { text: "Two models tie at 57, but the spread runs from 57 to 33 — a 73% gap from top to bottom.", options: { fontSize: 11, color: C.textMuted, breakLine: true } },
    { text: "", options: { breakLine: true, fontSize: 6 } },
    { text: "Open-weight GLM-5.1 (51) is within 10% of the leaders.", options: { fontSize: 11, color: C.accent, bold: true } }
  ], { x: 7.35, y: 1.25, w: 2.15, h: 1.9, margin: 0, valign: "top" });

  // Second card: Provider diversity
  mkCard(s, 7.1, 3.5, 2.6, 1.6);
  s.addShape(pres.shapes.RECTANGLE, {
    x: 7.1, y: 3.5, w: 0.06, h: 1.6,
    fill: { color: C.accent2 }
  });
  s.addText([
    { text: "Provider Spread", options: { bold: true, fontSize: 13, color: C.textDark, breakLine: true } },
    { text: "", options: { breakLine: true, fontSize: 6 } },
    { text: "8 organizations across the US, China, and Europe are represented — a genuinely global competition.", options: { fontSize: 11, color: C.textMuted } }
  ], { x: 7.35, y: 3.65, w: 2.15, h: 1.3, margin: 0, valign: "top" });

  addSource(s);
  addSlideNum(s, 2);
}

// ═══════════════════════════════════════════════════════
// SLIDE 3 — SPEED
// ═══════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };

  s.addText("gpt-oss-120B Tops Output Speed at 218 Tokens/s — More Than 4x Faster Than Claude Opus 4.6", {
    x: 0.5, y: 0.25, w: 9, h: 0.75,
    fontSize: 20, fontFace: "Georgia", color: C.textDark,
    bold: true, margin: 0
  });

  s.addChart(pres.charts.BAR, [{
    name: "Output Tokens/s",
    labels: speedData.map(d => d.model),
    values: speedData.map(d => d.speed)
  }], {
    x: 0.3, y: 1.1, w: 6.5, h: 4.0,
    barDir: "bar",
    chartColors: C.speedBars,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.textDark,
    dataLabelFontSize: 10,
    catAxisLabelColor: C.textDark,
    catAxisLabelFontSize: 9,
    valAxisHidden: true,
    catGridLine: { style: "none" },
    valGridLine: { color: C.border, size: 0.5 },
    showLegend: false,
    chartArea: { fill: { color: C.white }, roundedCorners: true }
  });

  // Callout: inverse correlation
  mkCard(s, 7.1, 1.1, 2.6, 2.2);
  s.addShape(pres.shapes.RECTANGLE, {
    x: 7.1, y: 1.1, w: 0.06, h: 2.2,
    fill: { color: C.accentRed }
  });
  s.addText([
    { text: "Speed ↔ Intelligence", options: { bold: true, fontSize: 13, color: C.textDark, breakLine: true } },
    { text: "", options: { breakLine: true, fontSize: 6 } },
    { text: "The fastest model (218 tokens/s) scores only 33 on intelligence. The smartest models run at 49–118 tokens/s.", options: { fontSize: 11, color: C.textMuted, breakLine: true } },
    { text: "", options: { breakLine: true, fontSize: 6 } },
    { text: "Open-weight models dominate throughput.", options: { fontSize: 11, color: C.accent2, bold: true } }
  ], { x: 7.35, y: 1.25, w: 2.15, h: 1.9, margin: 0, valign: "top" });

  // Callout: mid-range sweet spot
  mkCard(s, 7.1, 3.5, 2.6, 1.6);
  s.addShape(pres.shapes.RECTANGLE, {
    x: 7.1, y: 3.5, w: 0.06, h: 1.6,
    fill: { color: C.accent3 }
  });
  s.addText([
    { text: "Sweet Spot", options: { bold: true, fontSize: 13, color: C.textDark, breakLine: true } },
    { text: "", options: { breakLine: true, fontSize: 6 } },
    { text: "Gemini 3 Flash pairs 153 tokens/s with Intelligence 46 — a compelling balance for latency-sensitive apps.", options: { fontSize: 11, color: C.textMuted } }
  ], { x: 7.35, y: 3.65, w: 2.15, h: 1.3, margin: 0, valign: "top" });

  addSource(s);
  addSlideNum(s, 3);
}

// ═══════════════════════════════════════════════════════
// SLIDE 4 — PRICING
// ═══════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };

  s.addText("From $0.30 to $10 per Million Tokens: A 33x Pricing Gap Across Models", {
    x: 0.5, y: 0.25, w: 9, h: 0.75,
    fontSize: 20, fontFace: "Georgia", color: C.textDark,
    bold: true, margin: 0
  });

  s.addChart(pres.charts.BAR, [{
    name: "USD per 1M Tokens",
    labels: priceData.map(d => d.model),
    values: priceData.map(d => d.price)
  }], {
    x: 0.3, y: 1.1, w: 6.5, h: 4.0,
    barDir: "bar",
    chartColors: C.priceBars,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.textDark,
    dataLabelFontSize: 10,
    catAxisLabelColor: C.textDark,
    catAxisLabelFontSize: 9,
    valAxisHidden: true,
